impl<T: gx::Real> Vector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = t0 + t1;
        t2
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (10 mul, 3 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Vector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = t0 * t0;
        let t3 = t0 * t1;
        let t4 = t1 * t1;
        let t5 = t2 + t4;
        let t6 = t3 * T::from_i64(2);
        let t7 = t5 + t6;
        let t8 = t7.recip();
        let t9 = t0 * t8;
        let t10 = t1 * t8;
        let t11 = t9 + t10;
        let t12 = x[0] * t11;
        let t13 = x[1] * t11;
        Vector::from_coeffs([t12, t13])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = p0 + p1;
        let s0 = (p2).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        gx::Unit::new_unchecked(Vector::from_coeffs([t0, t1]))
    }

}

#[doc = "The unit area element `e12`."]
