impl<T: gx::Real> Pseudoscalar<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Pseudoscalar<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        let t5 = -t4;
        Pseudoscalar::from_coeffs([t5])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Pseudoscalar::from_coeffs([t0]))
    }

    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Rotor<(), T>> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = -p0;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs(-1, p1, T::from_i64(0));
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([c0, t0]))
    }

}

#[doc = "A rotor: the even subalgebra, isomorphic to the complex numbers."]
///
/// Blades, in coefficient order: `[1, e12]`.
///
/// `S` lists the open slots: `Rotor` (that is, `Rotor<()>`) is a value, `Rotor<(A,)>` a
/// linear map from `A`, `Rotor<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Rotor<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 2],
}

