impl<T: gx::Real> Rotor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = t0 + t1;
        t2
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (10 mul, 3 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Rotor<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = t0 * t0;
        let t3 = t0 * t1;
        let t4 = t1 * t1;
        let t5 = t2 + t4;
        let t6 = t3 * T::from_i64(2);
        let t7 = t5 + t6;
        let t8 = t7.recip();
        let t9 = t0 * t8;
        let t10 = t1 * t8;
        let t11 = t9 + t10;
        let t12 = x[0] * t11;
        let t13 = x[1] * t11;
        let t14 = -t13;
        Rotor::from_coeffs([t12, t14])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = p0 + p1;
        let s0 = (p2).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([t0, t1]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Rotor::from_coeffs(c).normalized()
    }

}

impl<T: gx::Real> gx::Log<Pseudoscalar<(), T>> for gx::Unit<Rotor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Pseudoscalar<(), T> {
        let x = self.into_inner().c;
        let p0 = x[1] * x[1];
        let p1 = -p0;
        let [h0, h1] = gx::study::log_coeffs(-1, (x[0], T::from_i64(0)), (p1, T::from_i64(0)));
        let t0 = x[1] * h0;
        Pseudoscalar::from_coeffs([t0])
    }
}

#[doc = "A general multivector."]
///
/// Blades, in coefficient order: `[1, e1, e2, e12]`.
///
/// `S` lists the open slots: `Multivector` (that is, `Multivector<()>`) is a value, `Multivector<(A,)>` a
/// linear map from `A`, `Multivector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Multivector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 4],
}

